<template>
 <div class="lobby" @pointerdown.capture="touch" @keydown.capture="touch" @input.capture="touch" @scroll.capture="recordActivity">
  <header class="hero" :style="{'--landscape':`url(${landscape})`}">
   <div class="hero-copy"><div class="eyebrow"><Building2 :size="17"/> WELCOME TO {{locationName||'OUR OFFICE'}}</div><h1>Make yourself <em>at home.</em></h1><div class="intro-row"><p>Choose your provider to check in, or explore the office directory.</p><div class="clock"><strong>{{clockTime}}</strong><span>{{clockDate}}</span></div></div></div>
  </header>
  <main>
   <nav ref="tabsElement" class="tabs" aria-label="Office views"><button v-for="item in tabs" :key="item.id" :class="{active:tab===item.id}" :aria-pressed="tab===item.id" @click="changeTab(item.id)"><component :is="item.icon" :size="19"/><span>{{item.label}}</span></button></nav>
   <KioskOfficeBoard v-if="tab==='offices'" :location-id="locationId"/>
   <section v-else-if="tab==='events'" class="coming"><CalendarDays :size="40"/><h2>Programs & events</h2><p>Coming soon</p><span>Discover groups, workshops, and ways to connect here at the office.</span></section>
   <div v-else class="workspace">
    <section class="providers-section"><div class="section-heading"><div><span class="eyebrow">{{tab==='current'?'CLIENT CHECK-IN':tab==='today'?'OUR OFFICE TODAY':'MEET OUR PROVIDERS'}}</span><h2>{{tab==='current'?'Who are you here to see?':tab==='today'?'Here today. Here for you.':'Find your connection.'}}</h2></div><label class="search"><Search :size="18"/><input v-model="query" type="search" aria-label="Search providers" placeholder="Search name, company, or specialty…"/><button v-if="query" aria-label="Clear search" @click="query=''"><X :size="16"/></button></label></div>
     <div class="filters"><button :class="{selected:!agencyFilter}" @click="agencyFilter=''">All organizations</button><button v-for="a in presentAgencies" :key="a.id" :class="{selected:agencyFilter===a.id}" @click="agencyFilter=a.id">{{a.name}}</button></div>
     <div v-if="tab==='current'" class="hour-row"><span>{{nextHour?'Early arrival · ':''}}{{formatKioskTime(windowStart)}} appointments</span><button @click="nextHour=!nextHour;loadSchedule()">{{nextHour?'Back to current hour':'More than 30 minutes early? Next hour'}}<ArrowRight :size="14"/></button></div>
     <div v-if="error" class="notice" role="alert">{{error}} <button @click="refresh">Try again</button></div><p v-if="loading" class="empty" role="status">Getting the office ready…</p>
     <div v-else-if="filteredProviders.length" class="provider-grid"><KioskProviderCard v-for="p in filteredProviders" :key="`${p.id}:${p.agencyId}`" :provider="p" :mode="tab" @select="selectProvider" @photo="photo=$event" @profile="showProfile"/></div>
     <div v-else-if="!error" class="empty"><h3>{{tab==='current'?'No matching appointments in this window.':'No providers match this search.'}}</h3><p>Your provider may still be here. Our support team can help.</p><button @click="openSupport">Don’t see your appointment? Message support</button></div>
     <button v-if="tab==='profiles'" class="show-more" @click="allProviders=!allProviders">{{allProviders?'Show providers with office bookings':'Show all providers from our office’s organizations'}}<ChevronDown :size="16"/></button>
    </section>
    <aside><div class="privacy-card"><ShieldCheck :size="28"/><h3>A simple,<br/>private arrival.</h3><p>Select your provider.<br/>We’ll let them know you’re here.</p><span>Check-in responses stay private.</span></div><div class="help-card"><h3>Need a hand?</h3><p>Don’t see your appointment?</p><button @click="openSupport"><MessageCircle :size="18"/> Message our support team<ArrowRight :size="16"/></button><small>This kiosk is still being improved. Your provider may still be at the office.</small></div></aside>
   </div>
  </main>
  <footer><span>{{locationName||'Office'}} · A warm welcome, a simple arrival.</span><button @click="reset(true)">Return to welcome screen</button></footer>
  <KioskCheckInFlow v-if="selectedProvider" :provider="selectedProvider" :location-id="locationId" :timezone="timezone" :direct-slot="selectedProvider.currentSlot" @close="selectedProvider=null" @checked-in="checkedIn" @arrival-recorded="markArrival" @busy="busy=$event"/>
  <KioskDialog v-if="dayProvider" :title="`${dayProvider.firstName} ${dayProvider.lastName} · Today`" @close="dayProvider=null"><p>Office hours and bookings for today. To check in, use Client check-in.</p><div v-for="b in dayProvider.bookings" :key="`${b.eventId}:${b.startAt}`" class="booking-row"><CalendarDays :size="18"/><div><strong>{{formatKioskTime(b.startAt)}}–{{formatKioskTime(b.endAt)}}</strong><span>{{b.roomNumber?`Office ${b.roomNumber}`:b.roomName}} · {{b.booked?'Booked':'Assigned office time'}}</span></div></div><button class="solid-button" @click="dayProvider=null;changeTab('current')">Go to client check-in</button></KioskDialog>
  <KioskDialog v-if="photo" :title="`${photo.firstName} ${photo.lastName}`" @close="photo=null"><img v-if="photo.profilePhotoPath" class="large-photo" :src="toUploadsUrl(photo.profilePhotoPath)" :alt="`${photo.firstName} ${photo.lastName}`"/><p v-else>No photo has been added yet.</p><button class="solid-button" @click="showProfile(photo);photo=null">View provider profile</button></KioskDialog>
  <KioskDialog v-if="profilePerson" :title="`${profilePerson.firstName} ${profilePerson.lastName}`" @close="closeProfile"><p v-if="profileLoading">Loading profile…</p><p v-else-if="profileError" role="alert">{{profileError}}</p><template v-else><div class="profile-intro"><button v-if="profilePerson.profilePhotoPath" @click="photo=profilePerson;closeProfile()"><img :src="toUploadsUrl(profilePerson.profilePhotoPath)" :alt="profilePerson.firstName"/></button><div><strong>{{profilePerson.credential}}</strong><p>{{profilePerson.agencyName}}</p></div></div><h3>About your provider</h3><p class="bio">{{profile.publicBlurb||'A biography has not been published yet.'}}</p><section v-for="group in profileGroups" :key="group.label"><h3>{{group.label}}</h3><div class="profile-tags"><span v-for="v in group.values" :key="v">{{v}}</span></div></section><section v-if="profile.selfPayRateCents!=null"><h3>Self-pay</h3><p>{{new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(profile.selfPayRateCents/100)}} · {{profile.selfPayRateNote||'Confirm details with the team.'}}</p></section></template></KioskDialog>
  <KioskSupportForm v-if="supportOpen" :location-id="locationId" :people="people" :agencies="agencies" @close="supportOpen=false" @sent="supportSent" @busy="busy=$event"/>
  <div v-if="thanks" class="thanks" role="status"><CheckCircle2 :size="27"/><div><strong>{{thanks==='support'?'Your message is on its way.':thanks==='already-arrived'?'This appointment is already checked in.':'Thank you. You’re checked in.'}}</strong><span>{{thanks==='support'?'Support and your provider have a secure app message.':'Your provider has been notified. Please settle into the waiting room.'}}</span></div><button aria-label="Dismiss confirmation" @click="thanks='' "><X :size="20"/></button></div>
  <KioskDialog v-if="idlePrompt&&!sleeping" title="All done?" @close="touch"><p>We’ll return to the welcome screen in {{idleRemaining}} seconds and clear this visit from the screen.</p><button class="solid-button" @click="touch">I’m still here</button><button class="text-button" @click="reset(true)">All done · Return to welcome</button></KioskDialog>
  <button v-if="sleeping" class="welcome-screen" :style="{'--landscape':`url(${landscape})`}" @click="wake" @keydown.enter.prevent="wake"><span class="welcome-location"><Building2 :size="24"/>{{locationName||'Welcome to our office'}}</span><span class="welcome-title">Welcome.<br/><em>Please check in.</em></span><span class="touch-prompt"><Hand :size="24"/>Touch anywhere to check in</span><span class="welcome-clock">{{clockTime}} · {{clockDate}}</span></button>
 </div>
</template>
<script setup>
import { useKioskTabScroll } from '../composables/useKioskTabScroll.js';

import {ref,computed,onMounted,onUnmounted,watch} from 'vue';import {useRoute} from 'vue-router';
import {Building2,CalendarCheck,Users,CalendarDays,LayoutGrid,Search,X,ArrowRight,ShieldCheck,MessageCircle,ChevronDown,CheckCircle2,Hand,ContactRound} from '@lucide/vue';
import api from '../services/api';import KioskProviderCard from '../components/kiosk/KioskProviderCard.vue';import KioskCheckInFlow from '../components/kiosk/KioskCheckInFlow.vue';import KioskOfficeBoard from '../components/kiosk/KioskOfficeBoard.vue';import KioskDialog from '../components/kiosk/KioskDialog.vue';import KioskSupportForm from '../components/kiosk/KioskSupportForm.vue';import {applyOfficeInstallIdentity} from '../utils/officeSite';import {formatKioskTime} from '../utils/kioskTime';import {toUploadsUrl} from '../utils/uploadsUrl';import {kioskMatches} from '../utils/kioskSearch';
const props=defineProps({locationId:{type:[String,Number],default:null}}),route=useRoute();const locationId=computed(()=>props.locationId||route.params.locationId);
const landscape=computed(()=>Number(locationId.value)===6?'/office/denver-skyline.webp':'/office/pikes-peak.webp');
const tab=ref('current'),query=ref(''),agencyFilter=ref(''),nextHour=ref(false),allProviders=ref(false),people=ref([]),agencies=ref([]),scheduled=ref([]),windowStart=ref(''),windowCloses=ref(''),locationName=ref(''),timezone=ref('America/Denver'),loading=ref(true),error=ref('');
const selectedProvider=ref(null),dayProvider=ref(null),photo=ref(null),profilePerson=ref(null),profile=ref({}),profileLoading=ref(false),profileError=ref(''),supportOpen=ref(false),busy=ref(false),thanks=ref(''),sleeping=ref(true),idlePrompt=ref(false),idleRemaining=ref(10),now=ref(new Date());
const tabsElement=ref(null);useKioskTabScroll(tabsElement,()=>!sleeping.value&&!selectedProvider.value&&!supportOpen.value&&!idlePrompt.value);
const tabs=[{id:'current',label:'Client check-in',icon:CalendarCheck},{id:'today',label:'Today’s providers',icon:Users},{id:'events',label:'Programs & events',icon:CalendarDays},{id:'offices',label:'Office directory',icon:LayoutGrid},{id:'profiles',label:'Providers',icon:ContactRound}];
const clockTime=computed(()=>now.value.toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',timeZone:timezone.value})),clockDate=computed(()=>now.value.toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric',timeZone:timezone.value}));
const sourceProviders=computed(()=>tab.value==='profiles'?people.value.filter(p=>allProviders.value||p.officeBooked):scheduled.value.filter(p=>tab.value==='today'||(!p.checkinClosesAt||Date.parse(p.checkinClosesAt)>now.value.getTime())));
const presentAgencies=computed(()=>[...new Map(sourceProviders.value.map(p=>[p.agencyId,{id:p.agencyId,name:p.agencyName}])).values()]);
const filteredProviders=computed(()=>sourceProviders.value.filter(p=>(!agencyFilter.value||p.agencyId===agencyFilter.value)&&kioskMatches([p.firstName,p.lastName,p.credential,p.title,p.agencyName,p.searchText].filter(Boolean).join(' '),query.value)));
const profileGroups=computed(()=>{const d=profile.value.details||{};return [{label:'Languages',values:d.languages},{label:'Specialties',values:d.specialties||d.focusAreas},{label:'Approaches',values:d.modalities||d.approaches},{label:'Client ages',values:d.ageGroups},{label:'Insurance accepted',values:profile.value.insurances}].filter(g=>Array.isArray(g.values)&&g.values.length);});
let scheduleVersion=0,peopleVersion=0,profileVersion=0,disposed=false,lastActivity=Date.now(),clockTimer,refreshTimer,thanksTimer;
async function loadSchedule(){const version=++scheduleVersion;try{const {data}=await api.get(`/kiosk/${locationId.value}/providers-today`,{params:{view:tab.value==='today'?'today':'current',nextHour:nextHour.value?'1':'0'},skipGlobalLoading:true});if(disposed||version!==scheduleVersion)return;scheduled.value=data.providers||[];locationName.value=data.locationName;timezone.value=data.timezone;windowStart.value=data.windowStartAt;windowCloses.value=data.windowClosesAt;error.value='';}catch{if(version===scheduleVersion)error.value='The schedule could not refresh. Please ask support if your appointment is missing.';}finally{if(version===scheduleVersion)loading.value=false;}}
async function loadPeople(){const version=++peopleVersion;try{const {data}=await api.get(`/public/office-lobby/${locationId.value}/people`,{skipGlobalLoading:true});if(disposed||version!==peopleVersion)return;people.value=data.people||[];agencies.value=data.agencies||[];}catch{if(version===peopleVersion)error.value='Provider information could not load. Please try again.';}}
async function refresh(){await Promise.all([loadSchedule(),loadPeople()]);}
function changeTab(value){tab.value=value;query.value='';agencyFilter.value='';nextHour.value=false;selectedProvider.value=null;loading.value=true;loadSchedule();}
function selectProvider(p){if(tab.value==='current'){if(!p.currentSlot?.checkedIn)selectedProvider.value=p;}else if(tab.value==='today')dayProvider.value=p;else showProfile(p);}
async function showProfile(p){profilePerson.value=p;profile.value={};profileError.value='';profileLoading.value=true;const version=++profileVersion;try{const {data}=await api.get(`/public/office-lobby/${locationId.value}/providers/${p.id}`,{params:{agencyId:p.agencyId},skipGlobalLoading:true});if(!disposed&&version===profileVersion)profile.value=data.profile||{};}catch{if(version===profileVersion)profileError.value='This profile could not load. Please try again later.';}finally{if(version===profileVersion)profileLoading.value=false;}}
function closeProfile(){profileVersion++;profilePerson.value=null;profile.value={};}
function openSupport(){supportOpen.value=true;if(!people.value.length)loadPeople();}
function recordActivity(event){if(event?.type==='scroll'&&event.target===tabsElement.value)return;if(!idlePrompt.value)touch();}
function touch(){lastActivity=Date.now();idlePrompt.value=false;idleRemaining.value=10;}
function reset(sleep=false){selectedProvider.value=null;dayProvider.value=null;photo.value=null;closeProfile();supportOpen.value=false;query.value='';agencyFilter.value='';allProviders.value=false;nextHour.value=false;tab.value='current';thanks.value='';sleeping.value=sleep;touch();loadSchedule();window.scrollTo?.({top:0,behavior:'instant'});}
function wake(){sleeping.value=false;touch();refresh();}
function showThanks(kind){reset(false);thanks.value=kind;clearTimeout(thanksTimer);thanksTimer=setTimeout(()=>{thanks.value='';},8000);}
function markArrival(){scheduleVersion++;const selected=selectedProvider.value;for(const person of scheduled.value){if(person.id===selected?.id&&person.currentSlot?.appointmentStartAt===selected.currentSlot?.appointmentStartAt)person.currentSlot.checkedIn=true;}}
function checkedIn(result){busy.value=false;showThanks(result?.alreadyCheckedIn?'already-arrived':'arrival');}function supportSent(){busy.value=false;showThanks('support');}
onMounted(()=>{for(const event of ['pointerdown','keydown','input','scroll'])document.addEventListener(event,recordActivity,true);applyOfficeInstallIdentity(locationId.value);refresh();clockTimer=setInterval(()=>{now.value=new Date();if(!sleeping.value&&!busy.value){const idle=Date.now()-lastActivity;if(idle>=70000){reset(true);return;}if(idle>=60000){idlePrompt.value=true;idleRemaining.value=Math.max(1,Math.ceil((70000-idle)/1000));}}if(windowCloses.value&&Date.parse(windowCloses.value)<=Date.now()){windowCloses.value='';loadSchedule();}},1000);refreshTimer=setInterval(loadSchedule,60000);});
watch(busy,value=>{if(!value)touch();});
watch(locationId,()=>{scheduleVersion++;peopleVersion++;reset(true);people.value=[];agencies.value=[];refresh();applyOfficeInstallIdentity(locationId.value);});
onUnmounted(()=>{for(const event of ['pointerdown','keydown','input','scroll'])document.removeEventListener(event,recordActivity,true);disposed=true;scheduleVersion++;peopleVersion++;profileVersion++;clearInterval(clockTimer);clearInterval(refreshTimer);clearTimeout(thanksTimer);});
</script>
<style scoped>
.lobby{--ink:#24443d;--muted:#6f7e71;min-height:100dvh;background:#f7f8f0;color:var(--ink);font-family:'Avenir Next','Segoe UI',sans-serif}.lobby *{box-sizing:border-box}button,input{font-family:inherit}.hero{background:linear-gradient(90deg,#f7f8f0f5 0%,#f7f8f0e0 43%,#f7f8f04a 100%),var(--landscape) center 48%/cover;padding:27px 5% 23px;border-bottom:1px solid #e0e6d7}.hero-copy{max-width:1440px;margin:auto}.eyebrow{display:flex;align-items:center;gap:8px;font-size:10px;letter-spacing:1.8px;font-weight:700;color:#728163}h1{font-size:clamp(36px,5vw,61px);line-height:1.08;letter-spacing:-2px;margin:13px 0 14px;font-weight:500}h1 em{font-family:Georgia,serif;color:#758754;font-weight:400}.intro-row{display:flex;align-items:center;justify-content:space-between;gap:25px}.intro-row p{font-size:14px;line-height:1.5;margin:0;color:#586d5d}.clock{text-align:right;flex-shrink:0;padding:5px 8px;border-radius:9px;background:#f7f8f0b8}.clock strong{display:block;font-size:23px;font-weight:500;letter-spacing:-.6px}.clock span{font-size:11px;color:#65775f}main{padding:22px 5% 40px;max-width:1600px;margin:auto}.tabs{display:flex;gap:9px;margin-bottom:30px;overflow-x:auto;padding:3px 0 8px}.tabs button{flex:1;display:flex;align-items:center;justify-content:center;gap:9px;white-space:nowrap;min-height:53px;padding:12px;border-radius:13px;border:1px solid #dfe5da;color:var(--ink);background:#fffefa;font-size:12px;cursor:pointer}.tabs button.active{background:#315e49;color:white;border-color:#315e49}.workspace{display:grid;grid-template-columns:minmax(0,1fr) 225px;gap:28px}.section-heading{display:flex;justify-content:space-between;align-items:center;gap:15px}h2{font-size:26px;font-weight:500;letter-spacing:-.8px;margin:9px 0 16px}.search{display:flex;align-items:center;gap:8px;background:#fffefa;border:1px solid #d6dfd0;border-radius:10px;padding:10px;min-width:170px;max-width:270px}.search input{border:0;outline:0;background:transparent;width:100%;min-width:0;font-size:12px;color:va