.welcome-title{font-size:clamp(48px,8vw,100px);line-height:1.12;letter-spacing:-2px}.welcome-title em{font-family:Georgia,serif;font-weight:400;color:#4a6c43}.touch-prompt{display:flex;align-items:center;gap:12px;padding:18px 25px;border-radius:40px;background:#315e49;color:white;font-size:17px;animation:welcome-pulse 3s ease-in-out infinite}.welcome-clock{font-size:14px;color:#61755d}button:focus-visible{outline:3px solid #b78432;outline-offset:4px}@keyframes welcome-pulse{50%{box-shadow:0 0 0 13px #315e4914;transform:scale(1.025)}}@keyframes thanks-in{from{opacity:0;transform:translate(-50%,15px)}to{opacity:1;transform:translate(-50%,0)}}@media(max-width:1180px){.provider-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.workspace{grid-template-columns:minmax(0,1fr) 205px;gap:20px}.section-heading{display:block}.search{max-width:none;margin-bottom:15px}.tabs button{font-size:11px;padding:10px 8px;gap:6px}.tabs button svg{width:16px}}@media(max-width:720px){.hero{padding:23px 22px}.intro-row{align-items:flex-end;gap:15px}.intro-row p{font-size:12px}.clock strong{font-size:18px}.clock span{font-size:9px}h1{font-size:40px}main{padding:16px 20px 30px}.tabs{gap:6px;margin-bottom:20px}.tabs button{flex:0 0 auto;padding:12px;min-height:48px}.workspace{grid-template-columns:1fr}.workspace aside{display:grid;grid-template-columns:1fr 1fr;gap:20px}.privacy-card{padding:22px}.privacy-card h3{font-size:24px}.provider-grid{gap:12px}h2{font-size:24px}.hour-row{align-items:start}.hour-row button{max-width:160px;text-align:right}.help-card{padding:15px 0}footer{flex-wrap:wrap}.welcome-screen{gap:30px}.touch-prompt{font-size:14px}}@media(max-width:430px){.provider-grid{grid-template-columns:1fr}.workspace aside{grid-template-columns:1fr}.intro-row{align-items:start}.clock span{max-width:105px;display:block}.thanks{padding:17px}.welcome-title{font-size:51px}}@media(prefers-reduced-motion:reduce){.touch-prompt,.thanks{animation:none}}
</style>
